#!/usr/bin/env python3
"""Publish one original guide per run; stop cleanly when the queue is exhausted."""
from datetime import datetime, timezone, timedelta
from html import escape as esc
from pathlib import Path
import xml.etree.ElementTree as ET
ROOT=Path(__file__).resolve().parent.parent
BASE='https://jinyou1129-bit.github.io/seoul-bites-guide/'
# slug, title, introduction, foods (name: advice), outing plan, question and answer
TOPICS=[
('hongdae-late-night-food-guide','Hongdae Late-Night Food Guide: What to Eat After Dark','Hongdae is a lively university neighborhood where a late dinner can be as casual as a snack between music venues.', [('Korean fried chicken (치킨)','Share a crispy or sweet-spicy portion; ask if half-and-half flavors are available.'),('Tteokbokki (떡볶이)','Chewy rice cakes in spicy sauce make a warming snack. Ask about the heat level.'),('Gimbap (김밥)','Seaweed rice rolls are portable; fillings range from vegetables and egg to tuna or meat.'),('Korean barbecue (고기구이)','For a longer meal, check the per-person minimum and total price before sitting down.')], 'Start with a small snack, then share a sit-down main. Plan the trip back: the subway does not run all night, and schedules vary.', 'Can I find food late at night in Hongdae?', 'Many restaurants serve dinner late, but individual kitchens close at different times. Check current hours before setting out.'),
('mangwon-market-food-guide','Mangwon Market Food Guide: A First-Timer’s Walk','Mangwon Market (망원시장) is a neighborhood market where visitors can build a meal from several small purchases.', [('Dakgangjeong (닭강정)','Crunchy chicken in a sweet or spicy glaze travels well; ask for a small portion.'),('Hotteok (호떡)','A griddled filled pancake is comforting. Let the very hot filling cool before biting.'),('Gimbap (김밥)','Choose rice rolls with the filling you like; ask about meat, egg or fish if avoiding them.'),('Mandu (만두)','Steamed or fried dumplings are easy to share. Ask about pork or seafood fillings.')], 'Browse before buying, then choose two or three snacks to share. Keep the aisles clear and take your packaging with you.', 'How long should I allow?', 'About one to two hours is a useful starting point for browsing and snacks; allow more for a sit-down meal.'),
('myeongdong-street-food-guide','Myeongdong Street Food Survival Guide','Myeongdong’s shopping streets offer a convenient introduction to snack-style eating; stalls and hours change.', [('Egg bread (계란빵)','Warm, lightly sweet bread with an egg makes an easy snack.'),('Hotteok (호떡)','Let the hot syrup cool before eating and check for nuts.'),('Tornado potato','A spiral-cut potato on a skewer is easy to share; seasoning may include dairy.'),('Grilled skewers (꼬치)','Check the ingredients, price and sauce before ordering.')], 'Walk the street once, compare prices, then share a couple of snacks. Dispose of skewers safely.', 'Are all stalls open every day?', 'No single schedule covers every vendor. Check current trading hours.'),
('korean-fried-chicken-and-beer-guide','Chimaek Guide: Korean Fried Chicken and Beer','Chimaek combines chicken (치킨) and beer (맥주), usually over a relaxed shared meal.', [('Original crispy chicken','Ask whether it is bone-in or boneless and how large the portion is.'),('Yangnyeom chicken (양념치킨)','Sweet-savory red sauce coats the chicken; heat levels vary.'),('Soy garlic chicken','A savory-sweet choice; the glaze may contain soy and wheat.'),('Pickled radish (치킨무)','Cool, crunchy radish is a common accompaniment; check if it costs extra.')], 'Share a chicken and order drinks to suit your group. Nonalcoholic drinks work too; never drink and drive.', 'Do I have to drink beer?', 'No. Soft drinks, water and nonalcoholic options are fine alternatives.'),
('seoul-convenience-store-meal-guide','Seoul Convenience Store Meal Guide','Convenience stores are useful for a quick meal between sightseeing stops. Selection varies by branch.', [('Samgak gimbap (삼각김밥)','Check the filling and follow the numbered wrapper tabs.'),('Cup ramyeon (컵라면)','Follow package directions and check the broth and spice level.'),('Dosirak (도시락)','A boxed meal may include rice, sides and a main; read reheating instructions.'),('Banana milk (바나나우유)','Check for milk and enjoy by the printed use-by date.')], 'Check labels and dates, use seating only where provided, and sort waste as instructed.', 'Are convenience-store meals vegetarian?', 'Not necessarily; broths, sauces and fillings can contain meat or seafood. Check ingredients.'),
('seoul-korean-barbecue-guide','Korean Barbecue in Seoul: A Beginner’s Guide','Korean barbecue is a social meal built around grilling meat and sharing side dishes. Menus and minimum orders differ.', [('Samgyeopsal (삼겹살)','Cook pork belly fully and use clean utensils for cooked meat.'),('Galbi (갈비)','Ribs may be marinated; ask which meat is offered and about allergens.'),('Ssam (쌈)','Wrap grilled meat with greens and a little sauce.'),('Banchan (반찬)','Side dishes vary and can contain seafood; ask about ingredients.')], 'Check the per-person minimum, order a manageable first round, and ask staff for help with the grill.', 'Will staff cook the meat?', 'Service varies. Some restaurants help at the table; others expect diners to grill their own.'),
('seoul-korean-noodle-guide','Korean Noodles in Seoul: What to Order','From warming broth to chilled noodles, Korean noodle dishes suit different seasons and appetites.', [('Kalguksu (칼국수)','Hand-cut wheat noodles often come in broth that may contain anchovy, shellfish or meat.'),('Naengmyeon (냉면)','Cold chewy noodles come in chilled broth or spicy sauce; ask about buckwheat.'),('Jjajangmyeon (짜장면)','Wheat noodles with dark bean sauce often contain pork.'),('Japchae (잡채)','Glass noodles are tossed with vegetables and sometimes meat; ask about soy and sesame.')], 'Choose hot or cold noodles to match the weather and check the broth or sauce.', 'Are noodle broths always vegetarian?', 'No. Anchovy, shellfish and meat broths are common, so check each dish.'),
('seoul-breakfast-food-guide','Breakfast in Seoul: What to Eat Before Sightseeing','Breakfast can be a bakery stop, a rice-and-soup meal or something quick from a convenience store.', [('Gimbap (김밥)','Rice rolls make a portable breakfast; check the filling.'),('Juk (죽)','Rice porridge varieties can contain vegetables, seafood or meat.'),('Bakery bread','A neighborhood bakery is convenient for coffee and a pastry; fillings vary.'),('Gukbap (국밥)','Rice with soup is hearty; ask about broth ingredients and portion size.')], 'Plan around your first attraction and verify morning opening times before traveling.', 'Do all restaurants serve breakfast?', 'No. Some open only for lunch or dinner, so confirm current hours.'),
('insadong-traditional-tea-houses', 'Insadong Traditional Tea Houses & Heritage Sweets', 'Explore traditional tea and sweets in Insadong.', [('Jujube tea (대추차)', 'A warming tea often served sweet.'), ('Omija tea (오미자차)', 'A berry infusion served hot or cold.'), ('Yakgwa (약과)', 'A wheat-based sweet; ask about honey and allergens.'), ('Rice cakes (떡)', 'Fillings vary; ask about nuts.')], 'Check tea-house hours, compare menus and share a pot with sweets.', 'Does all Korean tea contain caffeine?', 'No. Some fruit and herbal infusions do not; check the ingredients.'),
('myeongdong-kbbq-pork-belly-hanwoo', 'Myeongdong K-BBQ Guide: How to Order Pork Belly & Hanwoo Beef', 'Learn how to order barbecue in Myeongdong.', [('Samgyeopsal (삼겹살)', 'Cook pork belly fully.'), ('Hanwoo beef (한우)', 'Confirm cut, portion weight and price.'), ('Ssam (쌈)', 'Wrap cooked meat in greens with condiments.'), ('Banchan (반찬)', 'Ask about seafood and allergens.')], 'Check minimum orders and total cost, then ask staff for help with the grill.', 'Is Hanwoo always the same price?', 'No. Price depends on the cut, grade, portion and restaurant.'),
('seoul-vegetarian-vegan-without-fish-sauce', 'Seoul Vegetarian & Vegan Food Guide: Where to Eat Without Fish Sauce', 'Plan meals by asking about broths, sauces and preparation.', [('Bibimbap (비빔밥)', 'Ask about meat, egg and sauces.'), ('Tofu dishes', 'Ask if broth contains seafood or meat.'), ('Temple food (사찰음식)', 'Confirm ingredients and suitability.'), ('Vegetable gimbap (야채김밥)', 'Check for egg, fish cake and sauces.')], 'Check menus and contact restaurants in advance; explain dietary restrictions.', 'Is kimchi always vegan?', 'No. Kimchi can contain fish sauce or fermented seafood.'),
('seoul-chimaek-chicken-beer-combos', 'Chimaek Culture: Best Korean Fried Chicken & Beer Combos in Seoul', 'Chimaek is the tradition of sharing fried chicken and drinks.', [('Original chicken', 'Ask about bone-in or boneless portions.'), ('Yangnyeom chicken', 'Sweet-spicy sauce varies by restaurant.'), ('Soy garlic chicken', 'Check for soy and wheat.'), ('Drinks', 'Beer and nonalcoholic drinks are options; never drink and drive.')], 'Check prices and ask whether half-and-half flavors are available.', 'Must I order beer?', 'No. Water and nonalcoholic drinks are alternatives.'),
('mangwon-vs-gwangjang-market', 'Mangwon Market vs Gwangjang Market: Which Should You Visit?', 'Compare two markets when planning a food outing.', [('Mangwon Market', 'Browse neighborhood stalls and compare snacks.'), ('Gwangjang Market', 'Check food prices and seating before ordering.'), ('Mandu (만두)', 'Ask about meat or seafood fillings.'), ('Hotteok (호떡)', 'Let the filling cool and check for nuts.')], 'Choose based on location and hours; keep aisles clear and take packaging with you.', 'Can I visit both in one day?', 'It may be possible; allow for travel time and check current hours.'),
('seongsu-cafe-hopping-pastries', 'Seoul Cafe Hopping: Best Pastries and Aesthetic Coffee Shops in Seongsu', 'Seongsu has cafes and creative spaces with changing menus.', [('Coffee', 'Ask about milk alternatives.'), ('Salt bread (소금빵)', 'Ask about dairy and wheat.'), ('Croissants', 'Fillings may contain nuts or dairy.'), ('Seasonal desserts', 'Check ingredients and availability.')], 'Choose nearby cafes, verify current hours and allow walking time.', 'Do all cafes offer plant milk?', 'No. Availability differs by shop.'),
('korean-spice-level-survival', 'Spicy Food Survival Guide: Level 1 to Level 5 Korean Spice Explained', 'Spice scales vary by restaurant and are not universal.', [('Level 1: mild', 'Ask for no added chili when possible.'), ('Levels 2–3: moderate', 'Start small and confirm the restaurant’s own scale.'), ('Level 4: hot', 'Ask how the dish is seasoned.'), ('Level 5: very hot', 'Do not assume another restaurant uses the same scale.')], 'Discuss your tolerance with staff and start mild.', 'Are spice levels standardized?', 'No. Restaurants use different recipes and labels.'),
('seoul-food-allergy-ordering-guide', 'Seoul Food Allergy Guide: Questions to Ask Before Ordering', 'Ingredients and cross-contact vary by restaurant.', [('Broths', 'Ask about shellfish, fish and meat.'), ('Sauces', 'Check for soy, wheat, sesame, nuts and seafood.'), ('Fried foods', 'Ask about shared oil and surfaces.'), ('Desserts', 'Check for milk, eggs, wheat and nuts.')], 'Carry an allergy translation and avoid food if ingredients cannot be confirmed.', 'Can a dish be guaranteed allergen-free?', 'Ask the restaurant about ingredients and handling; cross-contact may still occur.'),
('seoul-solo-dining-guide', 'Solo Dining in Seoul: How to Find a Comfortable Meal', 'Solo travelers can look for individual portions and clear menus.', [('Gukbap (국밥)', 'Check the broth and portion.'), ('Kalguksu (칼국수)', 'Ask about broth ingredients.'), ('Gimbap (김밥)', 'Choose a suitable filling.'), ('Barbecue', 'Check the minimum order before sitting down.')], 'Check menus and hours and ask about minimum orders.', 'Can one person order Korean barbecue?', 'Policies differ; some restaurants have minimum orders.'),
('seoul-market-cash-card-guide', 'Seoul Food Markets: Cash, Cards & Ordering Tips', 'Prepare for different payment policies at markets and stalls.', [('Market snacks', 'Check prices and portions before ordering.'), ('Cash', 'Carry small notes as a backup.'), ('Cards', 'Ask each vendor whether cards are accepted.'), ('Takeaway', 'Ask about packaging or seating charges.')], 'Browse first, confirm payment and follow local waste-sorting instructions.', 'Do all stalls accept cards?', 'No. Payment policies vary by vendor.')]

# Per-slug card metadata: (filter category, card/sharing image, badge text)
U='https://images.unsplash.com/{}?auto=format&fit=crop&w=1200&q=80'
CARD_META={'hongdae-late-night-food-guide':('street',U.format('photo-1517154421773-0529f29ea451'),'Street Food'),'mangwon-market-food-guide':('market',U.format('photo-1553163147-622ab57be1c7'),'Markets'),'myeongdong-street-food-guide':('street',U.format('photo-1538485399081-7191377e8241'),'Street Food'),'insadong-traditional-tea-houses':('tradition',U.format('photo-1576092768241-dec231879fc3'),'Tradition'),'myeongdong-kbbq-pork-belly-hanwoo':('kbbq',U.format('photo-1546833999-b9f581a1996d'),'K-BBQ'),'mangwon-vs-gwangjang-market':('market',U.format('photo-1541696432-82c6da8ce7bf'),'Markets'),'seongsu-cafe-hopping-pastries':('cafe',U.format('photo-1554118811-1e0d58224f24'),'Cafe'),'seoul-chimaek-chicken-beer-combos':('street',U.format('photo-1612927601601-6638404737ce'),'Street Food'),'seoul-korean-barbecue-guide':('kbbq',U.format('photo-1546833999-b9f581a1996d'),'K-BBQ'),'seoul-vegetarian-vegan-without-fish-sauce':('tradition',U.format('photo-1590301157890-4810ed352733'),'Tradition')}
DEFAULT_CARD=('street',U.format('photo-1538485399081-7191377e8241'),'Street Food')

def render(t,date):
 slug,title,intro,foods,plan,q,a=t
 category,card_img,badge=CARD_META.get(slug,DEFAULT_CARD)
 og_img=card_img.replace('&','&amp;')
 og_block=(f'<meta property="og:type" content="article"><meta property="og:site_name" content="Seoul Bites Guide"><meta property="og:locale" content="en_US">'
  f'<meta property="og:title" content="{esc(title,quote=True)} - Seoul Bites Guide"><meta property="og:description" content="{esc(intro,quote=True)}">'
  f'<meta property="og:url" content="{BASE}{slug}.html"><meta property="og:image" content="{og_img}">'
  f'<meta property="og:image:width" content="1200"><meta property="og:image:height" content="630">'
  f'<meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{esc(title,quote=True)} - Seoul Bites Guide">'
  f'<meta name="twitter:description" content="{esc(intro,quote=True)}"><meta name="twitter:image" content="{og_img}">')
 items=''.join('<li><strong>'+esc(n)+':</strong> '+esc(d)+'</li>' for n,d in foods)
 faq=''.join('<div class="faq-item"><div class="faq-q">'+esc(x)+'</div><div class="faq-a">'+esc(y)+'</div></div>' for x,y in [(q,a),('How should I handle allergies?','Tell staff about your allergy and ask about ingredients and cross-contact. Never rely on appearance alone.'),('How much should I budget?','Prices vary by shop and portion. Check the displayed menu and confirm the total before ordering.'),('Can I pay by card?','Many businesses accept cards, but policies vary. Carry some cash as a backup.')])
 ad='<div class="ad-slot"><div class="ad-label">Advertisement</div><p>Ad space available &mdash; <a href="./advertise.html">advertise with us</a></p></div>'
 return f"""<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{esc(title)} - Seoul Bites Guide</title><meta name="description" content="{esc(intro,quote=True)}"><link rel="canonical" href="{BASE}{slug}.html">{og_block}<link rel="stylesheet" href="./style.css"></head><body><div class="top-bar">Brands: reach travelers planning Korea trips &mdash; <a href="./advertise.html">Advertise here</a></div><header><div class="logo"><a href="./index.html" style="color:var(--primary);text-decoration:none">Seoul Bites Guide</a></div><nav><a href="./index.html#guides">Guides</a><a href="./about.html">About</a><a href="./advertise.html">Advertise</a><a href="./contact.html">Contact</a></nav></header><main class="container"><div class="disclosure">Disclosure: This page may contain affiliate links. If you book through them, we may earn a commission at no extra cost. The buttons below are placeholders and do not yet lead to offers.</div><h1 style="font-size:2.1rem;margin-bottom:15px;line-height:1.25">{esc(title)}</h1><p style="color:var(--text-muted);margin-bottom:25px">Published {date}</p><p>{esc(intro)}</p><h2 style="font-size:1.4rem;margin:28px 0 12px;color:var(--primary)">What to try</h2><ul style="margin:12px 0 18px 20px">{items}</ul>{ad}<h2 style="font-size:1.4rem;margin:28px 0 12px;color:var(--primary)">A simple plan</h2><p>{esc(plan)}</p><div class="checklist"><h4>Before you order</h4><ul><li>Confirm prices, portions and payment methods before ordering.</li><li>Ask about allergens and cross-contact; recipes vary by vendor.</li><li>Check current hours and transport schedules; availability changes.</li></ul></div><h2>Optional experiences</h2><p>These buttons are placeholders, not active booking links.</p><div><a class="btn" href="#" rel="sponsored nofollow">Food tour (coming soon)</a><a class="btn btn-outline" href="#" rel="sponsored nofollow">Travel eSIM (coming soon)</a></div><div class="faq-box"><h3>Frequently Asked Questions</h3>{faq}</div>{ad}<div class="subscribe-box"><h3>Get Free Seoul Food Secrets</h3><p>Fresh food guides and practical tips for exploring Seoul.</p><form class="subscribe-form" action="https://formsubmit.co/6e050f7a56168f151155544eb83bea9a" method="POST"><input type="hidden" name="_subject" value="Newsletter signup from Seoul Bites Guide"><input type="hidden" name="_captcha" value="false"><input type="hidden" name="_next" value="{BASE}{slug}.html?subscribed=1"><input type="text" name="_honey" style="display:none" tabindex="-1" autocomplete="off"><input type="email" name="email" aria-label="Email address" placeholder="Your email address" required><button type="submit" class="btn">Subscribe</button></form><p class="form-note" id="sub-status" role="status" hidden style="display:none"><strong>Thanks! Your signup was sent.</strong> Look for Seoul food guides in your inbox.</p></div></main><footer><div><a href="./privacy.html">Privacy Policy</a> &bull; <a href="./about.html">About</a> &bull; <a href="./advertise.html">Advertise</a> &bull; <a href="./contact.html">Contact</a></div><div class="disclaimer">Prices and availability change. This is general travel information.</div><div>&copy; {date[:4]} Seoul Bites Guide.</div></footer><script src="./engage.js" defer></script><script>if(location.search.indexOf("subscribed=1")>-1){{var n=document.getElementById("sub-status");if(n){{n.hidden=false;n.style.display="block";}}}}</script></body></html>"""

def main():
 topic=next((t for t in TOPICS if not (ROOT/(t[0]+'.html')).exists()),None)
 if topic is None:
  print('Editorial queue exhausted; add new topics before the next post.'); return
 name=topic[0]+'.html'; date=datetime.now(timezone(timedelta(hours=9))).date().isoformat(); path=ROOT/'index.html'; index=path.read_text(encoding='utf-8'); marker='<div class="card-grid">'; href='./'+name
 if index.count(marker)!=1 or 'id="guides"' not in index: raise ValueError('Featured guides grid not found uniquely')
 if href in index: raise ValueError('Guide already linked; refusing duplicate')
 category,card_img,badge=CARD_META.get(topic[0],DEFAULT_CARD)
 short=topic[2] if len(topic[2])<=125 else topic[2][:122].rsplit(' ',1)[0]+'…'
 card=('<article class="card" data-category="'+category+'"><div class="card-img-wrapper"><img class="card-img" src="'+card_img.replace('&','&amp;')+'" alt="'+esc(topic[1],quote=True)+'" loading="lazy"><div class="card-overlay"><span class="badge-tag badge-'+category+'">'+badge+'</span><span class="badge reading-time">6 min read</span></div></div><h3><a class="card-link" href="'+href+'">'+esc(topic[1])+'</a></h3><p>'+esc(short)+'</p><a href="'+href+'">Read guide &rarr;</a></article>')
 ns='http://www.sitemaps.org/schemas/sitemap/0.9'; ET.register_namespace('',ns); site=ROOT/'sitemap.xml'
 if site.exists():
  tree=ET.parse(site); root=tree.getroot()
  if root.tag!='{'+ns+'}urlset': raise ValueError('Unsupported sitemap format')
 else:
  root=ET.Element('{'+ns+'}urlset'); tree=ET.ElementTree(root)
  for f in sorted(ROOT.glob('*.html')):
   u=ET.SubElement(root,'{'+ns+'}url'); ET.SubElement(u,'{'+ns+'}loc').text=BASE+f.name
 locs={x.text for x in root.findall('{'+ns+'}url/{'+ns+'}loc')}
 if BASE+name not in locs:
  u=ET.SubElement(root,'{'+ns+'}url'); ET.SubElement(u,'{'+ns+'}loc').text=BASE+name; ET.SubElement(u,'{'+ns+'}lastmod').text=date
 (ROOT/name).write_text(render(topic,date),encoding='utf-8'); path.write_text(index.replace(marker,marker+card,1),encoding='utf-8'); ET.indent(tree,space='  '); tree.write(site,encoding='utf-8',xml_declaration=True)
 print('Published',name,'on',date)
 try:
  import add_engage, add_seo_meta, add_structured_data, improve_seo, add_related_links, rebuild_sitemap
  add_seo_meta.main()
  improve_seo.main()
  add_related_links.main()
  add_structured_data.main()
  add_engage.main()
  rebuild_sitemap.main()
 except Exception as e:
  print('SEO blocks not refreshed:',e)
if __name__=='__main__': main()
